/** Lower-case ASCII URL segment: "Mercedes-Benz" → "mercedes-benz", "RS5 Coupé" → "rs5-coupe". */
export function slugifyCatalogLandingSegment(text: string): string {
  return text
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export function catalogLandingBrandSlug(label: string): string {
  return SHOP_CATALOG_LANDING_BRANDS[label]?.slug ?? slugifyCatalogLandingSegment(label);
}

export function catalogLandingBrandName(label: string): string {
  return SHOP_CATALOG_LANDING_BRANDS[label]?.name ?? label;
}

export const SHOP_CATALOG_LANDINGS = registry as readonly ShopCatalogLanding[];

const landingsByPath = new Map(SHOP_CATALOG_LANDINGS.map((landing) => [landing.path, landing]));

function normalizeLandingPath(path: string): string {
  return path
    .split("/")
    .map((segment) => {
      try {
        return decodeURIComponent(segment).trim().toLowerCase();
      } catch {
        return segment.trim().toLowerCase();
      }
    })
    .filter(Boolean)
    .join("/");
}

export function findShopCatalogLanding(path: string): ShopCatalogLanding | null {
  return landingsByPath.get(normalizeLandingPath(path)) ?? null;
}

/** The deepest existing landing above `path` (for URLs below the product threshold). */
export function findNearestShopCatalogLanding(path: string): ShopCatalogLanding | null {
  const segments = normalizeLandingPath(path).split("/");
  for (let length = segments.length - 1; length >= 2; length -= 1) {
    const landing = landingsByPath.get(segments.slice(0, length).join("/"));
    if (landing) return landing;
  }
  return null;
}

export function shopCatalogLandingHref(locale: string, landing: Pick<ShopCatalogLanding, "path">) {
  return `/${locale}/shop/${landing.path}`;
}

/** The catalog filters a landing page fixes, as catalog URL parameters. */
export function shopCatalogLandingFilters(landing: ShopCatalogLanding): Record<string, string> {
  const filters: Record<string, string> = {};
  if (landing.brand) filters.brand = landing.brand;
  if (landing.scope) filters.scope = landing.scope;
  if (landing.category) filters.category = landing.category;
  if (landing.make) filters.make = landing.make;
  if (landing.model) filters.model = landing.model;
  return filters;
}

/**
 * The landing's own query string may only carry `page` (and the display-only
 * `view`); any other filter makes it a filtered catalog view, which stays out
 * of the index like every filtered catalog URL.
 */
export function shopCatalogLandingQuery(searchParams: StockPageSearchParams) {
  const query = stockPageSearchParams(searchParams);
  return {
    page: parseStockPage(query.get("page")),
    filtered: hasStockCatalogFilters(query),
  };
}

/** The catalog query a landing page searches: its own filters win over the URL's. */
export function shopCatalogLandingSearch(
  landing: ShopCatalogLanding,
  searchParams: StockPageSearchParams
): StockPageSearchParams {
  const query = stockPageSearchParams(searchParams);
  const merged: Record<string, string | string[]> = {};
  for (const key of new Set(query.keys())) merged[key] = query.getAll(key);
  return { ...merged, ...shopCatalogLandingFilters(landing) };
}

// ---------- copy ----------

export type ShopCatalogLandingStats = {
  total: number;
  /** Category key → product count. */
  categories: Readonly<Record<string, number>>;
  /** Catalog brand label → product count. */
  brands: Readonly<Record<string, number>>;
};

export type ShopCatalogLandingCrumb = { name: string; href?: string };

export type ShopCatalogLandingCopy = {
  h1: string;
  title: string;
  description: string;
  breadcrumbs: ShopCatalogLandingCrumb[];
};

function topKeys(counts: Readonly<Record<string, number>>, limit: number, minimum = 1): string[] {
  return Object.entries(counts)
    .filter(([, count]) => count >= minimum)
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([key]) => key);
}

function isCategoryKey(key: string): key is ShopCatalogLandingCategoryKey {
  return key in SHOP_CATALOG_LANDING_CATEGORIES;
}

function categoryKeys(keys: string[]): ShopCatalogLandingCategoryKey[] {
  return keys.filter(isCategoryKey);
}

function fitTitle(head: string, items: string[]): string {
  for (let count = items.length; count > 0; count -= 1) {
    const title = `${head} — ${items.slice(0, count).join(", ")}${TITLE_SUFFIX}`;
    if (title.length <= SHOP_CATALOG_LANDING_TITLE_MAX) return title;
  }
  return `${head}${TITLE_SUFFIX}`;
}

function firstFitting(...candidates: string[]): string {
  return (
    candidates.find((candidate) => candidate.length <= SHOP_CATALOG_LANDING_TITLE_MAX) ??
    candidates[candidates.length - 1]
  );
}

function listUa(items: string[]): string {
  return items.length < 2 ? (items[0] ?? "") : `${items.slice(0, -1).join(", ")} і ${items.at(-1)}`;
}

function listEn(items: string[]): string {
  return items.length < 2
    ? (items[0] ?? "")
    : `${items.slice(0, -1).join(", ")} and ${items.at(-1)}`;
}

function pluralUa(count: number, one: string, few: string, many: string): string {
  const mod10 = count % 10;
  const mod100 = count % 100;
  if (mod10 === 1 && mod100 !== 11) return one;
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return few;
  return many;
}

function countUa(count: number): string {
  return `${count.toLocaleString("uk-UA").replace(/\s/g, " ")} ${pluralUa(count, "товар", "товари", "товарів")}`;
}

function countEn(count: number): string {
  return `${count.toLocaleString("en-US")} ${count === 1 ? "part" : "parts"}`;
}

const DELIVERY = {
  ua: "Ціни в гривнях, доставка по Україні.",
  en: "Delivery across Ukraine and worldwide.",
} as const;

function catalogCrumb(locale: "ua" | "en"): ShopCatalogLandingCrumb {
  return { name: locale === "ua" ? "Каталог" : "Catalog", href: `/${locale}/shop/catalog` };
}

function landingCrumb(locale: "ua" | "en", path: string, name: string): ShopCatalogLandingCrumb {
  const landing = landingsByPath.get(path);
  return landing ? { name, href: shopCatalogLandingHref(locale, landing) } : { name };
}

function brandCrumb(locale: "ua" | "en", label: string): ShopCatalogLandingCrumb {
  const name = catalogLandingBrandName(label);
  const hub = landingsByPath.get(`brand/${catalogLandingBrandSlug(label)}`);
  return hub ? { name, href: shopCatalogLandingHref(locale, hub) } : { name };
}

/**
 * Heading, title, description and breadcrumbs for a landing page, built from
 * the live counts of its own search so the copy follows the catalog.
 */
export function buildShopCatalogLandingCopy(
  locale: "ua" | "en",
  landing: ShopCatalogLanding,
  stats: ShopCatalogLandingStats | null
): ShopCatalogLandingCopy {
  const ua = locale === "ua";
  const total = stats?.total || landing.count;
  const categories = categoryKeys(topKeys(stats?.categories ?? {}, 3));
  const brands = topKeys(stats?.brands ?? {}, 4);
  const brandNames = brands.map(catalogLandingBrandName);
  const shortCats = categories.map((key) =>
    ua
      ? SHOP_CATALOG_LANDING_CATEGORIES[key].ua.short
      : SHOP_CATALOG_LANDING_CATEGORIES[key].en.short
  );
  const delivery = DELIVERY[locale];
  const root = catalogCrumb(locale);

  if (landing.kind === "make" || landing.kind === "model") {
    const subject = [landing.make, landing.model].filter(Boolean).join(" ");
    const crumbs: ShopCatalogLandingCrumb[] =
      landing.kind === "make"
        ? [root, { name: landing.make ?? "" }]
        : [
            root,
            landingCrumb(locale, landing.path.split("/").slice(0, 2).join("/"), landing.make ?? ""),
            { name: landing.model ?? "" },
          ];
    const head = ua ? `Тюнінг ${subject}` : `${subject} tuning parts`;
    return {
      h1: head,
      title: fitTitle(head, shortCats),
      description: ua
        ? `${countUa(total)} для ${subject}${brandNames.length ? `: ${listUa(brandNames)}` : ""}. ${delivery}`
        : `${countEn(total)} for ${subject}${brandNames.length ? ` from ${listEn(brandNames)}` : ""}. ${delivery}`,
      breadcrumbs: crumbs,
    };
  }

  if (landing.kind === "category" && landing.category) {
    const copy = SHOP_CATALOG_LANDING_CATEGORIES[landing.category];
    const make = landing.make ?? "";
    const topBrands = brandNames.slice(0, 3);
    const head = ua ? `${copy.ua.name} для ${make}` : `${make} ${copy.en.noun}`;
    return {
      h1: head,
      title: fitTitle(head, topBrands),
      description: ua
        ? `${countUa(total)} — ${copy.ua.name.toLowerCase()} для ${make}${topBrands.length ? `: ${listUa(topBrands)}` : ""}. ${delivery}`
        : `${countEn(total)} — ${copy.en.noun} for ${make}${topBrands.length ? ` from ${listEn(topBrands)}` : ""}. ${delivery}`,
      breadcrumbs: [
        root,
        landingCrumb(locale, landing.path.split("/").slice(0, 2).join("/"), make),
        { name: ua ? copy.ua.name : copy.en.noun },
      ],
    };
  }

  const label = landing.brand ?? "";
  const name = catalogLandingBrandName(label);
  const minimum = Math.max(landing.kind === "brand" ? 3 : 2, Math.round(total * 0.1));
  const brandCats = categoryKeys(topKeys(stats?.categories ?? {}, 2, minimum));
  const uaCats = brandCats.map((key) => SHOP_CATALOG_LANDING_CATEGORIES[key].ua.name.toLowerCase());
  const enShort = brandCats.map((key) => SHOP_CATALOG_LANDING_CATEGORIES[key].en.short);

  if (landing.kind === "brand") {
    let enNouns = brandCats.map((key) => SHOP_CATALOG_LANDING_CATEGORIES[key].en.noun);
    // "Fi Exhaust exhaust systems" → "Fi Exhaust systems".
    if (name.toLowerCase().includes("exhaust")) {
      enNouns = enNouns.map((noun) => (noun === "exhaust systems" ? "systems" : noun));
    }
    const uaList = uaCats.join(", ");
    const enList = enNouns.join(" & ");
    return {
      h1: name,
      title: ua
        ? firstFitting(
            ...(uaList
              ? [
                  `${name}: ${uaList} — купити в Україні${TITLE_SUFFIX}`,
                  `${name}: ${uaList}${TITLE_SUFFIX}`,
                ]
              : []),
            `${name}${TITLE_SUFFIX}`
          )
        : firstFitting(
            ...(enList
              ? [
                  `${name} ${enList} — online store${TITLE_SUFFIX}`,
                  `${name} ${enList}${TITLE_SUFFIX}`,
                ]
              : []),
            `${name}${TITLE_SUFFIX}`
          ),
      description: ua
        ? `${countUa(total)} ${name}${uaList ? `: ${uaList}` : ""}. ${delivery}`
        : `${countEn(total).replace(/ parts?$/, "")} ${name} ${total === 1 ? "part" : "parts"}${enShort.length ? `: ${enShort.join(", ")}` : ""}. ${delivery}`,
      breadcrumbs: [root, { name }],
    };
  }

  const make = landing.make ?? "";
  const head = ua ? `${name} для ${make}` : `${name} for ${make}`;
  const uaShort = brandCats.map((key) => SHOP_CATALOG_LANDING_CATEGORIES[key].ua.short);
  return {
    h1: head,
    title: fitTitle(head, ua ? uaShort : enShort),
    description: ua
      ? `${countUa(total)} ${name} для ${make}${uaCats.length ? `: ${uaCats.join(", ")}` : ""}. ${delivery}`
      : `${countEn(total).replace(/ parts?$/, "")} ${name} ${total === 1 ? "part" : "parts"} for ${make}${enShort.length ? `: ${enShort.join(", ")}` : ""}. ${delivery}`,
    breadcrumbs: [root, brandCrumb(locale, label), { name: make }],
  };
}

export type ShopCatalogLandingLinkGroup = {
  title: string;
  links: Array<{ name: string; href: string }>;
};

const LINKS_PER_GROUP = 12;

function categoryLinkName(locale: "ua" | "en", key: ShopCatalogLandingCategoryKey): string {
  const copy = SHOP_CATALOG_LANDING_CATEGORIES[key];
  if (locale === "ua") return copy.ua.name;
  return copy.en.noun.charAt(0).toUpperCase() + copy.en.noun.slice(1);
}

function linkGroup(
  locale: "ua" | "en",
  title: string,
  landings: readonly ShopCatalogLanding[],
  name: (landing: ShopCatalogLanding) => string
): ShopCatalogLandingLinkGroup[] {
  const links = [...landings]
    .sort((a, b) => b.count - a.count)
    .slice(0, LINKS_PER_GROUP)
    .map((landing) => ({ name: name(landing), href: shopCatalogLandingHref(locale, landing) }));
  return links.length ? [{ title, links }] : [];
}

/**
 * Links from a landing page to its neighbours: a make to its models,
 * categories and brands, a model to the make's other models, a brand to its
 * makes. They are how shoppers (and crawlers) move between landing pages.
 */
export function buildShopCatalogLandingLinks(
  locale: "ua" | "en",
  landing: ShopCatalogLanding
): ShopCatalogLandingLinkGroup[] {
  const ua = locale === "ua";
  const others = SHOP_CATALOG_LANDINGS.filter((item) => item.path !== landing.path);
  const ofMake = (kind: ShopCatalogLandingKind) =>
    others.filter((item) => item.kind === kind && item.make === landing.make);
  const categoryName = (item: ShopCatalogLanding) =>
    item.category ? categoryLinkName(locale, item.category) : "";
  const make = landing.make ?? "";

  switch (landing.kind) {
    case "make":
      return [
        ...linkGroup(locale, ua ? "Моделі" : "Models", ofMake("model"), (item) => item.model ?? ""),
        ...linkGroup(locale, ua ? "Категорії" : "Categories", ofMake("category"), categoryName),
        ...linkGroup(locale, ua ? "Бренди" : "Brands", ofMake("brandMake"), (item) =>
          catalogLandingBrandName(item.brand ?? "")
        ),
      ];
    case "model":
      return [
        ...linkGroup(
          locale,
          ua ? `Інші моделі ${make}` : `Other ${make} models`,
          ofMake("model"),
          (item) => item.model ?? ""
        ),
        ...linkGroup(
          locale,
          ua ? `Категорії ${make}` : `${make} categories`,
          ofMake("category"),
          categoryName
        ),
      ];
    case "category":
      return linkGroup(
        locale,
        ua ? `Інші категорії ${make}` : `Other ${make} categories`,
        ofMake("category"),
        categoryName
      );
    case "brand":
      return linkGroup(
        locale,
        ua ? "Марки авто" : "Vehicle makes",
        others.filter((item) => item.kind === "brandMake" && item.brand === landing.brand),
        (item) => item.make ?? ""
      );
    case "brandMake":
      return linkGroup(
        locale,
        ua
          ? `${catalogLandingBrandName(landing.brand ?? "")} для інших марок`
          : `${catalogLandingBrandName(landing.brand ?? "")} for other makes`,
        others.filter((item) => item.kind === "brandMake" && item.brand === landing.brand),
        (item) => item.make ?? ""
      );
  }
}

/** The vehicle makes with the most products, for links from the main catalog. */
export function popularShopCatalogMakeLandings(limit = 12): ShopCatalogLanding[] {
  return SHOP_CATALOG_LANDINGS.filter((item) => item.kind === "make")
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/** Live counts of a landing's search response (`filterStats`). */
export function shopCatalogLandingStatsFromResponse(response: {
  meta?: { totalItems?: number };
  filterStats?: {
    categories?: ReadonlyArray<{ key?: string; label: string; count: number }>;
    brands?: ReadonlyArray<{ label: string; count: number }>;
  };
}): ShopCatalogLandingStats {
  return {
    total: response.meta?.totalItems ?? 0,
    categories: Object.fromEntries(
      (response.filterStats?.categories ?? [])
        .filter((row) => row.key)
        .map((row) => [row.key as string, row.count])
    ),
    brands: Object.fromEntries(
      (response.filterStats?.brands ?? []).map((row) => [row.label, row.count])
    ),
  };
}
